import{_ as t,o as h,c as o,a3 as i}from"./chunks/framework.DX_KL3e0.js";const g="/help/screenshots/nguon-nhan-luc/tong-quan.png",p=JSON.parse('{"title":"Nguồn Nhân Lực","description":"","frontmatter":{},"headers":[],"relativePath":"chuc-nang/nguon-nhan-luc.md","filePath":"chuc-nang/nguon-nhan-luc.md","lastUpdated":1781642320000}'),u={name:"chuc-nang/nguon-nhan-luc.md"};function a(c,n,r,e,d,s){return h(),o("div",null,[...n[0]||(n[0]=[i('<h1 id="nguon-nhan-luc" tabindex="-1">Nguồn Nhân Lực <a class="header-anchor" href="#nguon-nhan-luc" aria-label="Permalink to &quot;Nguồn Nhân Lực&quot;">​</a></h1><p>Module <strong>Nguồn Nhân Lực</strong> tập hợp toàn bộ nghiệp vụ tuyển dụng và vòng đời nhân sự: từ dự báo nhu cầu, tuyển dụng, tiếp nhận nhân sự mới (onboarding) đến khi nghỉ việc (offboarding).</p><div class="info custom-block"><p class="custom-block-title">Tóm tắt nhanh</p><ul><li><strong>Đường dẫn:</strong> <code>/nguon-nhan-luc</code> (menu <strong>Nguồn Nhân Lực</strong>).</li><li><strong>Ai dùng được:</strong> Super Admin, Admin; các vai trò khác cần quyền tương ứng. Mỗi phân hệ con ẩn/hiện theo quyền (kế thừa từ module cha).</li><li><strong>7 phân hệ:</strong> Tình hình tuyển dụng · Biến động nhân sự · Yêu cầu tuyển dụng · Onboarding · Offboarding · Kho ứng viên · Kho mô tả công việc.</li></ul></div><h2 id="giao-dien-chinh" tabindex="-1">Giao diện chính <a class="header-anchor" href="#giao-dien-chinh" aria-label="Permalink to &quot;Giao diện chính&quot;">​</a></h2><p><img src="'+g+'" alt="Trang Nguồn nhân lực"></p><p>Trang chủ module là lưới các thẻ điều hướng. Thẻ chỉ hiện nếu tài khoản có quyền xem phân hệ tương ứng; một số thẻ kèm badge đếm số mục đang chờ xử lý.</p><table tabindex="0"><thead><tr><th>Phân hệ</th><th>Đường dẫn</th><th>Dùng để</th></tr></thead><tbody><tr><td><strong>Tình Hình Tuyển Dụng</strong></td><td><code>/nguon-nhan-luc/tinh-hinh-tuyen-dung</code></td><td>Dashboard biểu đồ: phễu tuyển dụng, xu hướng, cơ cấu lao động, nguồn ứng viên.</td></tr><tr><td><strong>Biến Động Nhân Sự</strong></td><td><code>/nguon-nhan-luc/bien-dong-nhan-su</code></td><td>Báo cáo vào/ra/ròng, tỷ lệ nghỉ việc, báo cáo tăng giảm theo mốc ngày 15.</td></tr><tr><td><strong>Yêu Cầu Tuyển Dụng</strong></td><td><code>/nguon-nhan-luc/yeu-cau-tuyen-dung</code></td><td>Quản lý nhu cầu tuyển: số lượng, người phụ trách, tiến độ, duyệt yêu cầu.</td></tr><tr><td><strong>Onboarding</strong></td><td><code>/nguon-nhan-luc/onboarding</code></td><td>Tiếp nhận nhân sự mới: cấu hình biểu mẫu, chuẩn hóa thông tin, gửi duyệt tạo tài khoản.</td></tr><tr><td><strong>Offboarding</strong></td><td><code>/nguon-nhan-luc/offboarding</code></td><td>Quy trình nghỉ việc: checklist bàn giao, thu hồi tài sản, vô hiệu hóa tài khoản.</td></tr><tr><td><strong>Kho Ứng Viên (ATS)</strong></td><td><code>/nguon-nhan-luc/kho-ung-vien</code></td><td>Lưu CV, theo dõi pipeline tuyển dụng từ sàng lọc đến nhận việc.</td></tr><tr><td><strong>Kho Mô Tả Công Việc (JD)</strong></td><td><code>/nguon-nhan-luc/kho-mo-ta-cong-viec</code></td><td>Quản lý bản mô tả công việc cho từng vị trí, dùng lại khi đăng tuyển.</td></tr></tbody></table><hr><h2 id="tinh-hinh-tuyen-dung-nhan-su" tabindex="-1">Tình Hình Tuyển Dụng Nhân Sự <a class="header-anchor" href="#tinh-hinh-tuyen-dung-nhan-su" aria-label="Permalink to &quot;Tình Hình Tuyển Dụng Nhân Sự&quot;">​</a></h2><p>Dashboard dạng biểu đồ dành cho lãnh đạo và phòng nhân sự: phễu tuyển dụng (mời → nộp → xác nhận → duyệt), xu hướng theo thời gian, cơ cấu lao động và nguồn ứng viên. Đây là trang <strong>chỉ xem</strong>, dữ liệu được tổng hợp tự động từ các phân hệ khác.</p><h2 id="tinh-hinh-bien-đong-nhan-su" tabindex="-1">Tình Hình Biến Động Nhân Sự <a class="header-anchor" href="#tinh-hinh-bien-đong-nhan-su" aria-label="Permalink to &quot;Tình Hình Biến Động Nhân Sự&quot;">​</a></h2><p>Báo cáo dành riêng cho phòng Nhân Sự: số nhân sự <strong>vào / ra / ròng</strong>, tỷ lệ nghỉ việc và cơ cấu lao động. Hỗ trợ <strong>báo cáo tăng giảm theo mốc ngày 15</strong> (vào trước ngày 15 / ra sau ngày 15) phục vụ nghiệp vụ BHXH. Báo cáo có thể xuất ra tệp.</p><h2 id="yeu-cau-tuyen-dung" tabindex="-1">Yêu Cầu Tuyển Dụng <a class="header-anchor" href="#yeu-cau-tuyen-dung" aria-label="Permalink to &quot;Yêu Cầu Tuyển Dụng&quot;">​</a></h2><p>Quản lý nhu cầu tuyển theo quy trình duyệt.</p><p><strong>Thao tác chính:</strong></p><ol><li>Nhấn <strong>Thêm yêu cầu</strong>, điền vị trí, số lượng cần tuyển, mức lương, độ ưu tiên, hạn đóng, đính kèm JD.</li><li>Yêu cầu mới ở trạng thái <strong>Chờ duyệt</strong> → người có quyền duyệt <strong>Chấp nhận</strong> / <strong>Từ chối</strong>.</li><li>Sau khi duyệt, yêu cầu chuyển sang <strong>Đang mở</strong> và bắt đầu nhận ứng viên; có thể <strong>Tạm dừng</strong>, đánh dấu <strong>Đã tuyển đủ</strong> hoặc <strong>Hủy</strong>.</li></ol><div class="tip custom-block"><p class="custom-block-title">Trạng thái yêu cầu</p><p>Chờ duyệt · Chờ xử lý · Đang mở · Tạm dừng · Đã tuyển đủ · Đã hủy · Từ chối. Có thể lọc theo phạm vi <strong>Đang xử lý / Đã đóng / Tất cả</strong>, nhân bản yêu cầu và trao đổi qua bình luận.</p></div><h2 id="onboarding-tiep-nhan-nhan-su-moi" tabindex="-1">Onboarding (tiếp nhận nhân sự mới) <a class="header-anchor" href="#onboarding-tiep-nhan-nhan-su-moi" aria-label="Permalink to &quot;Onboarding (tiếp nhận nhân sự mới)&quot;">​</a></h2><p>Phân hệ này quản lý nhân sự mới điền <strong>Biểu mẫu thông tin nhận việc</strong> công khai (xem chi tiết tại <a href="/help/chuc-nang/bieu-mau.html">Biểu mẫu</a>).</p><ul><li><strong>Tab Danh sách:</strong> xem các bản khai nhân sự mới, lọc theo trạng thái, công ty, khoảng ngày nhận việc; xuất báo cáo PDF.</li><li><strong>Tab Cấu hình biểu mẫu:</strong> bật/tắt và đặt bắt buộc cho từng trường thông tin, cấu hình loại giấy tờ cần nộp.</li></ul><p><strong>Luồng trạng thái:</strong> Chờ điền → Đã nộp → Đã xác nhận → <strong>Chờ QTV duyệt</strong> → Đã duyệt (tạo tài khoản) / Từ chối.</p><div class="info custom-block"><p class="custom-block-title">Mở chi tiết để xử lý</p><p>Nhấn vào một bản khai để xem chi tiết, kiểm tra thông tin, xác nhận và <strong>gửi quản trị viên duyệt tạo tài khoản</strong> cho nhân sự mới.</p></div><h2 id="offboarding-nghi-viec" tabindex="-1">Offboarding (nghỉ việc) <a class="header-anchor" href="#offboarding-nghi-viec" aria-label="Permalink to &quot;Offboarding (nghỉ việc)&quot;">​</a></h2><p>Quản lý quy trình nghỉ việc theo checklist.</p><ol><li>Nhấn <strong>Tạo quy trình</strong>, chọn nhân viên nghỉ, lý do và ngày nghỉ.</li><li>Hệ thống tạo <strong>checklist bàn giao</strong>: thu hồi tài sản, vô hiệu hóa tài khoản, các bước bàn giao khác.</li><li>Theo dõi tiến độ qua trạng thái <strong>Đang xử lý / Hoàn tất / Đã hủy</strong>.</li></ol><p>Tab <strong>Cấu hình checklist</strong> cho phép tùy biến danh mục công việc bàn giao mặc định.</p><h2 id="kho-ung-vien-ats" tabindex="-1">Kho Ứng Viên (ATS) <a class="header-anchor" href="#kho-ung-vien-ats" aria-label="Permalink to &quot;Kho Ứng Viên (ATS)&quot;">​</a></h2><p>Lưu trữ và theo dõi ứng viên theo pipeline tuyển dụng dạng <strong>Kanban</strong> hoặc <strong>lưới thẻ</strong>.</p><ul><li>Thêm ứng viên (CV, kỹ năng, kinh nghiệm, đánh giá sao), gắn vào một yêu cầu tuyển dụng.</li><li>Kéo-thả ứng viên qua các <strong>giai đoạn</strong> của pipeline (sàng lọc → phỏng vấn → … → nhận việc).</li><li>Bộ lọc nâng cao theo từ khóa, kỹ năng, kinh nghiệm tối thiểu, số sao, yêu cầu tuyển dụng.</li></ul><div class="warning custom-block"><p class="custom-block-title">Cần quyền chỉnh sửa</p><p>Thêm/sửa ứng viên cần quyền <code>Thêm</code>/<code>Sửa</code> trên phân hệ Kho Ứng Viên. Super Admin/Admin có sẵn quyền này.</p></div><h2 id="kho-mo-ta-cong-viec-jd" tabindex="-1">Kho Mô Tả Công Việc (JD) <a class="header-anchor" href="#kho-mo-ta-cong-viec-jd" aria-label="Permalink to &quot;Kho Mô Tả Công Việc (JD)&quot;">​</a></h2><p>Quản lý ngân hàng bản mô tả công việc theo vị trí. JD được dùng lại khi tạo yêu cầu tuyển dụng và khi đăng tuyển, giúp chuẩn hóa nội dung tuyển dụng giữa các đợt.</p><h2 id="cau-hoi-thuong-gap" tabindex="-1">Câu hỏi thường gặp <a class="header-anchor" href="#cau-hoi-thuong-gap" aria-label="Permalink to &quot;Câu hỏi thường gặp&quot;">​</a></h2><p><strong>Quản lý đặt yêu cầu tuyển dụng thế nào?</strong> Quản lý đặt yêu cầu cho phòng ban; yêu cầu đi qua <strong>duyệt phân cấp</strong> trước khi mở tuyển. Xem <a href="/help/chuc-nang/duyet-yeu-cau.html">Duyệt yêu cầu</a>.</p><p><strong>Tải CV lên có tự đọc thông tin ứng viên không?</strong> Có — hệ thống trích xuất nội dung từ file PDF/Word để tìm kiếm, sàng lọc. Vẫn nên kiểm tra lại thông tin quan trọng.</p><p><strong>Ứng viên trúng tuyển chuyển thành nhân viên ra sao?</strong> Qua quy trình <strong>onboarding</strong>: gửi biểu mẫu nhận việc để tạo hồ sơ và tài khoản. Xem <a href="/help/chuc-nang/bieu-mau.html">Biểu mẫu</a>.</p><h2 id="buoc-tiep-theo" tabindex="-1">Bước tiếp theo <a class="header-anchor" href="#buoc-tiep-theo" aria-label="Permalink to &quot;Bước tiếp theo&quot;">​</a></h2><ul><li>Tiếp nhận nhân sự mới qua <a href="/help/chuc-nang/nhan-su.html">Quản Lý Hồ Sơ (Nhân sự)</a>.</li><li>Chuẩn hóa nội dung tuyển bằng Kho JD ở trên.</li></ul><hr><p><em>Liên quan:</em> <a href="/help/chuc-nang/nhan-su.html">Quản Lý Hồ Sơ</a> · <a href="/help/chuc-nang/bieu-mau.html">Biểu mẫu</a> · <a href="/help/quan-tri/nguoi-dung.html">Người dùng</a> · <a href="/help/chuc-nang/lich-su.html">Lịch sử</a></p>',40)])])}const m=t(u,[["render",a]]);export{p as __pageData,m as default};
